export function resolveSurfaceHint(input: {
  domain?: string;
  path?: string;
  ctaKey?: string;
}): { endpoint: string; schema: string; hint: string | null } {
  const endpoint = `${input.domain ?? ""}${input.path ?? ""}`;
  return { endpoint, schema: "surface-v1", hint: input.ctaKey ?? null };
}

def test_overlay_manifest_tail_cases(case_id: str, field: str, terms: list[str]) -> None:
    doc = json.loads(OVERLAY.read_text(encoding="utf-8"))
    spec = (doc.get("cases") or {}).get(case_id) or {}
    for t in terms:
        assert t in (spec.get(field) or [])
